def test_dist_facade_list_attributes() -> None:
    from pluggy._compat import DistFacade

    fc = DistFacade(distribution("pluggy"))
    res = dir(fc)
    assert res == sorted(res)
    assert set(res) - set(dir(fc._dist)) == {"_dist", "project_name"}
